class MyFlowExample {
  // Maximum retry attempts
  private readonly MAX_ATTEMPTS = 5;

  // Wait time in ms between attempts
  private readonly RETRY_DELAY_MS = 3000;

  // The repository (or any other dependency) is injected
  constructor(private repository: ExampleRepository) {}

  /**
   * Asynchronous generator that executes the retry logic.
   */
  async* processOrder(request: MyRequest): AsyncGenerator<string, HTTPResolved<MyResponseData>, unknown> {
    let attempts = 0;

    while (attempts < this.MAX_ATTEMPTS) {
      yield `Attempt ${attempts + 1} of ${this.MAX_ATTEMPTS}`;

      // Placeholder call to get order status
      const statusResponse = await this.repository.getStatus(request);

      yield `Repository response code: ${statusResponse.code}`;

      // Check if the process is completed
      if (statusResponse.data.completed) {
        const orderCode = statusResponse.data.code || "N/A";
        yield `Process completed. Fetching additional info for: ${orderCode}`;

        // Placeholder call to get additional data
        const additionalResponse = await this.repository.getAdditionalInfo(orderCode);

        yield `Additional data received. Code: ${additionalResponse.code}`;

        // Return the final structure
        return {
          code: 200,
          data: {
            orderCode,
            additionalInfo: additionalResponse.data.info
          }
        };
      }

      attempts++;

      // If it's not completed yet and there are still retries available
      if (attempts < this.MAX_ATTEMPTS) {
        yield `Incomplete status. Retrying in ${this.RETRY_DELAY_MS / 1000} seconds...`;
        await this.delay();
        yield "Resuming process after wait.";
      }
    }

    // If the max number of retries was reached, throw an error
    throw new Error("Could not complete order status retrieval.");
  }

  /**
   * Method to execute the generator and consume its values.
   */
  async runProcess(request: MyRequest): Promise<HTTPResolved<MyResponseData>> {
    const generator = this.processOrder(request);

    let result: HTTPResolved<MyResponseData> | null = null;
    let done = false;

    while (!done) {
      const { value, done: generatorDone } = await generator.next();
      done = generatorDone ?? false;

      // If the value is not a string, it should be the final response
      if (value && typeof value !== "string") {
        result = value;
      }

      // You can log or handle each status message here
      if (typeof value === "string") {
        console.info(value);
      }
    }

    if (result) {
      return result;
    }

    // If there's no result at this point, throw an error
    throw new Error("Failed to obtain the final response.");
  }

  /**
   * Small helper to wait for X milliseconds
   */
  private async delay(): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, this.RETRY_DELAY_MS));
  }
}
